      const chk = (key, label, title) => { const l = mk("label", "chk", null, { title }), c = mk("input", "", null, { type: "checkbox", checked: r[key] }); c.onchange = () => { r[key] = c.checked; keep(); drawRules(); }; l.append(c, label); return l; };
