    if (!name) return;
    const at = sets.findIndex(s => s.name === name);
    if (at < 0 && sets.length >= MAX_SETS) { StatusBar.msg(T("Đã đủ {n} bộ — xoá bớt trước.", { n: MAX_SETS }), "warn"); return; }
