    foot.append(button(T("+ Thêm dòng"), () => { rules.push(BatchRules.blank()); keep(); drawRules(); }), mk("span", "muted", T("Phạm vi: vùng chọn nếu có, không thì cả tab.")), go, button(T("Đóng"), () => dlg.close()));
