  const clean = o => ({ pattern: str(o?.pattern, 2000, ""), flags: str(o?.flags, 8, "g"), replace: str(o?.replace, 2000, "") });
  const opts = srcId => PowerUi.opts(srcId, "regex", clean, DEF);

