        if (!v.seq) { const out = Docs.get(p.doc); con.replaceChildren(mk("div", "rp-none", T("Bấm ▶ Chạy lại để chạy (code không tự chạy lại sau khi tải lại trang)."))); if (out) con.append(mk("pre", "run-old", Docs.text(out))); }
