    const head = r.items.length ? T("{n} lỗi cú pháp · {lang} · {engine}", { n: I18n.num(r.items.length), lang: c.lang, engine: r.engine }) : T("✔ Không thấy lỗi cú pháp · {lang} · {engine}", { lang: c.lang, engine: r.engine });
