    const r = Invisible.scan(t);
    const lines = r.items.map(i => i.line + ":" + i.col + "\t" + i.code + "\t" + i.name);
    return { text: lines.join("\n") + (lines.length ? "\n" : ""), view: { kind: "invisible", srcId: c.id, ...r }, notes: [T("{n} ký tự vô hình / lạ.", { n: I18n.num(r.total) })] };
